@register.simple_tag
def icon(name, size=20, class_name="", stroke_width=1.8):
    """Rend une icône SVG inline (style Lucide, trait cohérent)."""
    paths = ICONS.get(name, ICONS["circle-help"])
    classes = f"h-{size} w-{size} shrink-0 {class_name}".strip()
    return mark_safe(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" '
        f'stroke="currentColor" stroke-width="{stroke_width}" '
        'stroke-linecap="round" stroke-linejoin="round" '
        f'class="{classes}" aria-hidden="true">{paths}</svg>'
    )